// Builds printable HTML documents (payment receipt, student statement) for
// Phase 4 ("Rapports & impression" — see docs/electron-app-plan.md section
// 5/8). Rendered to PDF by the caller via `webContents.printToPDF` (see
// ipc.ts) — this service only produces self-contained HTML strings (inline
// CSS, no external network requests), since the PDF is generated by loading
// a `data:` URL in a hidden BrowserWindow.
//
// Respects `document_language_mode` (fr_only / en_only / bilingual_fr_en) and
// `receipt_paper_format` (A4 / ticket) from settings.
import fs from 'node:fs';
import type { Kysely } from 'kysely';
import type { Database } from '../db/schema-types';
import {
  PrintLabels,
  paperFormatFromSetting,
  type DocumentLanguageMode,
  type ReceiptPaperFormat,
} from './print-labels';
import { pdfFileName } from './print-file-name';
import {
  amountInWordsEn,
  amountInWordsFr,
} from '../../../shared/amount-words';
import { formatCurrency } from '../../../shared/currency';

export interface PrintDocument {
  html: string;
  defaultFileName: string;
  /** Paper format the caller should pass to printToPDF (see pdfOptionsForPaperFormat). */
  paperFormat: ReceiptPaperFormat;
  /**
   * "Document generated on …" note, rendered in the PDF page footer (A4
   * only) instead of the document body, so it can never spill onto a lone
   * extra trailing page when the last content page is nearly full.
   */
  footerNote?: string;
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function formatAmount(amount: number, currency: string): string {
  return formatCurrency(amount, currency);
}

/** Same as formatAmount but wraps negative values in a red highlight. */
function formatSignedAmount(amount: number, currency: string): string {
  const text = formatAmount(amount, currency);
  return amount < 0 ? `<span class="neg">${text}</span>` : text;
}

const STATUS_TONES: Record<string, string> = {
  // Transactions
  ['Validé']: 'ok',
  ['Annulé']: 'danger',
  // Enrollment balances
  ['Payé']: 'ok',
  ['Paiement partiel']: 'warn',
  ['Non payé']: 'danger',
  ['Trop-perçu']: 'info',
  // Enrollments / staff
  ['Actif']: 'ok',
  ['Retiré']: 'warn',
  ['Suspendu']: 'warn',
  ['Sorti']: 'neutral',
};

/** Renders a status value as a colored pill (falls back to neutral). */
function statusPill(status: string): string {
  const tone = STATUS_TONES[status] ?? 'neutral';
  return `<span class="pill pill--${tone}">${escapeHtml(status)}</span>`;
}

interface SchoolInfo {
  schoolName: string;
  schoolShortName: string | null;
  countryName: string | null;
  printHeaderLine: string | null;
  address: string | null;
  phone: string | null;
  email: string | null;
  directorName: string | null;
  receiptMessage: string | null;
  currency: string;
  logoDataUri: string | null;
}

interface PrintContext {
  labels: PrintLabels;
  paperFormat: ReceiptPaperFormat;
  languageMode: DocumentLanguageMode;
  /** Set by wrapDocument(); the "generated on …" text for the PDF footer. */
  footerNote?: string;
}

